const READER_ORIGINAL_FEEDBACK = [
 ["7–8", ["akten gelesen", "Vorwissen verwenden", "publikum (?:darf|stimmt|wirkt).{0,24}(?:gar )?nicht (?:mit )?(?:ab|abstimmen|mit)"], "Der Vorsitzende verlangt, Vorwissen auszublenden. Das Publikum entscheidet als Schöffen allein nach den erhobenen Beweisen.", "Das Stück beginnt mit der direkten Ansprache vor dem Vorhang. Die Schauspieler verkörpern Richter, Anklage, Verteidigung, Angeklagten und weitere Beteiligte; das Publikum übernimmt tatsächlich die Abstimmung. Der Vergleich mit dem Thing zeigt, wie gemeinsames Sprechen über eine Tat helfen soll, Ordnung wiederherzustellen. Das Gericht spricht rechtliche Urteile und verdammt keine Menschen als böse.", ["Der Vorsitzende setzt das Publikum als Schöffen ein. Es stimmt über Lars Koch ab und soll ausschliesslich die in der Hauptverhandlung erhobenen Beweise berücksichtigen.", "Die Prozessbeteiligten rekonstruieren die bereits geschehene Tat durch Sprache. Der Vorsitzende vergleicht den Gerichtssaal mit einer Bühne und fordert ein besonnenes Urteil über einen Menschen."]],
 ["7–9", ["regieanweisungen werden laut vorgelesen", "kursiv.*dialog", "kursiv\\\\w* text (?:gehoert zum|ist) (?:gesprochenen? )?dialog"], "Kursive Passagen sind Anweisungen für die Aufführung. Die Figuren sprechen den Dialog in Normalschrift.", "Der erste Regieabschnitt zeigt den Vorsitzenden vor geschlossenem Vorhang, den nächsten Auftritt und das Überziehen der Robe. Lesende erschliessen daraus, wie sich Personen bewegen und welche sichtbaren Veränderungen die Aufführung zeigen soll.", ["Die kursiven Passagen sind Regieanweisungen. Sie bestimmen unter anderem Auftritte, Bewegungen, Sprechweisen und Ausstattung. Auf der Bühne werden sie umgesetzt. Beim Lesen stellt man sich das Geschehen anhand dieser Angaben vor."]],
 ["7–9", ["richtertisch steht hinter der zelle", "koch traegt eine richterrobe", "(?:angeklagte|koch) traegt (?:eine )?(?:polizei|richter)uniform"], "Der Richtertisch steht mittig und Koch trägt Luftwaffenuniform. Die Zelle befindet sich hinter dem Verteidiger.", "Zuerst tritt der Vorsitzende vor den Vorhang. Der Wachtmeister meldet Bieglers Ankunft. Nach dem Auftritt des Vorsitzenden im Saal stehen alle auf. Für die Skizze: hinten Mitte Richtertisch, rechts daran Protokollführerin; links Nelson und tiefer Meiser; rechts Biegler und hinter ihm Koch; vorne Mitte Zeugenplatz; Wachtmeister an der Tür.", ["In der Mitte steht der Richtertisch mit Vorsitzendem und Protokollführerin, davor der Zeugenplatz. Links sitzen Nelson und Meiser, rechts Biegler, dahinter Koch in einer Zelle. Der Wachtmeister sitzt an der Tür.", "Roben und Uniformen machen die institutionellen Rollen sichtbar. Koch trägt Luftwaffenuniform. Biegler trägt zunächst keine Robe. Der Vorsitzende legt seine Robe nach der Publikumsansprache an."]],
 ["9–12", ["koch in der zelle bleibt", "koch soll in der zelle bleiben", "(?:verteidiger|biegler) (?:will|moechte) koch (?:hinter gittern|in der zelle) lassen"], "Biegler beantragt, dass Koch neben ihm Platz nimmt. Der Vorsitzende gestattet es.", "Die Sitzung beginnt mit der Feststellung der Besetzung und der Anwesenheit von Nelson, Biegler und Koch. Der Vorsitzende lässt Koch aus der Zelle zum Verteidiger holen, befragt ihn zu seinen Personalien und bittet danach um Verlesung der Anklage. Biegler möchte wegen der schlechten Luft das Fenster öffnen; der Vorsitzende verweist auf den Lärm und bittet ihn, seine Robe anzuziehen.", ["Der Vorsitzende eröffnet die Sitzung, stellt die Beteiligten fest und klärt Kochs Personalien. Biegler bittet darum, dass Koch neben ihm Platz nimmt. Vor der Anklage bittet er ausserdem darum, ein Fenster zu öffnen.", "Koch ist Major der Luftwaffe und wird aus der Untersuchungshaft vorgeführt. Die Befragung liefert auch Angaben zu Familie und Beruf."]],
 ["12–13", ["fahrlaessiger toetung", "totschlag angeklagt", "nelson wirft ihm (?:nur )?eine fahrlaessige tat vor"], "Nelson klagt Koch wegen Mordes mit gemeingefährlichen Mitteln an.", "Die Anklage legt ihm die absichtliche Tötung der 164 Menschen an Bord zur Last. Sie benennt Ort, Datum, Zeitpunkt und Tatmittel und stellt den Abschuss als Gegenstand der Hauptverhandlung fest.", ["Nelson wirft Koch vor, am 26. Mai 2013 um 20.21 Uhr über Oberappersdorf ein Lufthansa-Passagierflugzeug abgeschossen und alle 164 Menschen an Bord mit gemeingefährlichen Mitteln getötet zu haben.", "Die Staatsanwaltschaft wertet die Tat als Mord. Das ist der Vorwurf, über den das Gericht erst entscheiden muss."]],
 ["14–16", ["bestreitet den abschuss", "stadion sei leer", "(?:verteidigung|biegler) (?:leugnet|bestreitet) die toetung der passagiere"], "Biegler räumt den Abschuss ein und schildert ein voll besetztes Stadion.", "Biegler ergänzt die Perspektive der Anklage um Entführung, drohenden Einschlag und die erwarteten Opfer im Stadion. Der Rettungszweck bildet den Ausgangspunkt für seine Verteidigung. Das Eingeständnis des Abschusses entscheidet die Schuldfrage deshalb noch nicht.", ["Biegler schildert das entführte Flugzeug auf Kurs zum voll besetzten Stadion. Er räumt den Abschuss ein und stellt ihm die Rettung der rund 70 000 Zuschauer gegenüber.", "Er trennt den eingeräumten äusseren Ablauf von der umstrittenen rechtlichen Bewertung und kündigt an, die Entscheidung aus der damaligen Lage zu erklären."]],
 ["17–23, 38–40", ["als zeuge jederzeit schweigen", "lauterbach darf immer schweigen", "lauterbach braucht (?:als zeuge )?(?:ueberhaupt )?nichts zu sagen"], "Lauterbach muss als Zeuge grundsätzlich wahrheitsgemäss und vollständig antworten. Seine Aussagegenehmigung nimmt Dienstgeheimnisse aus. Koch darf als Angeklagter zur Sache schweigen.", "Beim Entführungsfunkspruch reagiert Lauterbach, indem er die Meldung für den ganzen Raum hörbar macht und die zuständigen Stellen sowie Radtke informiert. Auf Nelsons Nachfrage räumt er später ein, dass er sich einen Abschuss durch Koch vorstellen konnte. Er lässt offen, ob er selbst ebenso gehandelt hätte. Das Gericht prüft bei dieser Frage auch eine mögliche Selbstbelastung und verlangt hier eine Antwort.", ["Lauterbach ist Oberstleutnant und war am betreffenden Tag ab 14 Uhr als Duty Controller im Lagezentrum im Einsatz. Seine Gedanken schildert er bei der Rekonstruktion der Meldungen und Entscheidungen unter Zeitdruck.", "Als Zeuge muss er vollständig und wahrheitsgemäss aussagen. Bei Dienstgeheimnissen darf er gemäss seiner Aussagegenehmigung die Auskunft verweigern und muss das offen sagen. Koch darf als Angeklagter zur Sache schweigen."]],
 ["19–24", ["nato bleibt.*allein zustaendig", "nato entscheidet.*abschuss", "nach der entfuehrung entscheidet (?:ausschliesslich|allein) die nato"], "Bei einer Entführung im deutschen Luftraum wechselt die Zuständigkeit zum nationalen Lage- und Führungszentrum.", "Das Zentrum führt militärische und zivile Informationen zusammen. Auffälligkeiten werden überprüft und können zur Einstufung als Renegade führen. Die Alarmrotte stellt Kontakt her und meldet Beobachtungen. Radar und Funk liefern unterschiedliche Informationen und erlauben keinen sicheren Einblick in das Innere der Maschine.", ["Die NATO überwacht den deutschen Luftraum. Bei einer Entführung im deutschen Luftraum geht die Zuständigkeit an das Nationale Lage- und Führungszentrum über.", "Dort werden Radar- und Funkinformationen sowie Meldungen ziviler und militärischer Stellen zu einem Lagebild zusammengeführt. Bei einem verdächtigen Flug klärt die Alarmrotte die Lage aus der Luft."]],
 ["22–29", ["radtke.*aus dem cockpit", "radtke flog", "radtke (?:erfaehrt|hoert) erst nach dem (?:absturz|abschuss) davon"], "Radtke führt die Lage als Inspekteur der Luftwaffe aus der Befehlskette. Koch ist der Pilot in der Luft.", "Lauterbach schaltet den Funkspruch für alle im Raum laut, setzt einen Ringruf ab und verständigt Radtke. Radtke fragt nach der Alarmrotte, lässt die Maschine abdrängen und berichtet über die weitere Lage an den Minister. Im Lagezentrum suchen die Beteiligten zugleich einen geeigneten Landeplatz. Meldungen gehen von der Alarmrotte über Lauterbach an Radtke; Entscheidungen gelangen über die Kette zurück.", ["Nach der Entführungsmeldung verfolgen die Beteiligten im Lagezentrum die Lage gemeinsam. Lauterbach informiert Generalleutnant Radtke, der zunächst nach dem Stand der Alarmrotte fragt und dann die Intervention befiehlt.", "Die Alarmrotte meldet ihre Beobachtungen an Lauterbach. Er meldet an Radtke weiter. Für die nächste Eskalationsstufe trägt Radtke die Lage und seinen Vorschlag dem Verteidigungsminister vor."]],
 ["24–27", ["abdraengen kam vom entfuehrer", "entfuehrer befahl.*abdraeng", "lauterbach gibt (?:sofort )?(?:den )?befehl (?:zur vernichtung|zum abschuss) der maschine"], "Der Interventionsbefehl stammt von Radtke. Lauterbach leitet ihn an Kochs Alarmrotte weiter.", "Der Auftrag lautet, die Maschine abzudrängen und zur Landung zu bringen. Koch führt als Major die Alarmrotte, beobachtet das Flugzeug und meldet den Verlauf zurück. Die Freigabe einer weiteren Stufe liegt bei der zuständigen Führung.", ["Lauterbach gibt Radtkes Interventionsbefehl an die Alarmrotte weiter. Die Maschine soll abgedrängt und zur Landung gezwungen werden.", "Major Koch ist der verantwortliche Pilot der Alarmrotte. Er führt die Massnahmen in der Luft aus und meldet seine Beobachtungen an das Lagezentrum zurück."]],
 ["26–31", ["minister.*abschuss (genehmigt|erlaubt|befohlen)", "abschussbefehl erhalten", "minister (?:gibt|gab) gruenes licht fuer (?:den abschuss|die toetung der passagiere)"], "Der Minister lehnt Radtkes Abschussvorschlag ab. Koch erhält die Weisung, nicht zu schiessen, und lässt sie zweimal bestätigen.", "Lauterbach meldet Radkte die erfolglosen Massnahmen und den fortgesetzten Kurs auf das Stadion. Radtke berät den Minister. Auf das Abdrängen folgt der freigegebene Warnschuss, anschliessend lehnt der Minister die letzte Stufe ab. Für Koch entsteht damit eine Lage, in der das Militär keinen erlaubten Abschuss anordnen kann, während er einen Einschlag befürchtet. Die verfassungsrechtliche Lücke betrifft die fehlende Ermächtigung zum Abschuss eines Flugzeugs mit unschuldigen Menschen an Bord. Das Gericht prüft Kochs individuelle strafrechtliche Verantwortung gesondert.", ["Lauterbach meldet Radtke den fortgesetzten Kurs auf das Stadion. Radtke schlägt dem Verteidigungsminister den Abschuss als letzte Stufe vor. Der Minister lehnt ab.", "Koch erhält die Weisung, dass nicht geschossen werden darf, und lässt sich das zweimal bestätigen. Die verfassungsrechtliche Grenze betrifft die staatliche Ermächtigung, ein Flugzeug mit unschuldigen Menschen abzuschießen. Die individuelle Strafbarkeit Kochs ist eine gesonderte Frage."]],
 ["31–34", ["schoss um 19 32", "abschuss.*19 32", "(?:schuss|abschuss) (?:faellt|erfolgt|erfolgte) (?:bereits )?um 19 32"], "19.32 Uhr ist die Zeit des ersten Funkspruchs. Lauterbach nennt 20.21 Uhr und 34 Sekunden als Zeitpunkt der Auslösung.", "Koch bestätigt zweimal das Abschussverbot, meldet den Sinkflug und warnt vor Zehntausenden Toten. Danach löst er das Geschoss aus. Die Maschine stürzt auf einem Acker ab. Alle 164 Menschen an Bord sterben. Die Alarmrotte kehrt zurück, Koch wird nach der Landung festgenommen und Radtke lässt die Aufzeichnungen sichern.", ["Koch fragt zweimal nach dem Befehl, meldet den Sinkflug und erklärt, ohne seinen Eingriff würden Zehntausende sterben. Die Maschine ist noch etwa 25 Kilometer vom Stadion entfernt.", "Koch löst das Geschoss aus. Der Abschuss erfolgt um 20.21 Uhr. Alle 164 Menschen an Bord sterben. Lauterbach rekonstruiert den Vorgang anhand von Funk und Bildschirm."]],
 ["35–40", ["jung.*ausnahmsloses abschussverbot", "alle.*wussten sicher", "jung (?:schloss|schliesst) einen eingriff (?:in jedem fall|grundsaetzlich) aus"], "Jung stellte einen Eingriff unter Berufung auf den übergesetzlichen Notstand in Aussicht. Lauterbach räumt eine Erwartung ein; Gewissheit aller Beteiligten ist damit nicht bewiesen.", "Nelson geht von der unterlassenen Räumung über den Zeitvergleich zu der Frage, ob man auf Koch gesetzt habe. Sie fragt auch, ob Lauterbach selbst geschossen hätte. Jung dient ihr als Beleg dafür, dass ein eigenverantwortlicher Abschuss in der Truppe diskutiert wurde. Der übergesetzliche Notstand ist hier der mögliche ungeschriebene Entschuldigungsgrund für eine extreme Konfliktlage.", ["Nelson fragt nach der unterlassenen Räumung und hakt nach, ob man auf Kochs Abschuss vertraute. Lauterbach sagt erst Nein und räumt dann ein, er habe sich vorstellen können, dass Koch schiessen würde. Das belegt keine Gewissheit des gesamten Bodenpersonals.", "Die Frage nach der Haltung des früheren Verteidigungsministers Jung führt zum übergesetzlichen Notstand. Gemeint ist ein möglicher, gesetzlich nicht geregelter Entschuldigungsgrund für eine extreme Konfliktlage."]],
 ["35–41", ["stadion wurde (rechtzeitig |bereits )?(geraeumt|evakuiert)", "notfallplan.*52 minuten", "zuschauer wurden (?:noch )?vor dem abschuss (?:evakuiert|in sicherheit gebracht)"], "Das Stadion wurde nicht geräumt. Die 52 Minuten bezeichnen das Zeitfenster; der Notfallplan nennt 15 Minuten für die Räumung.", "Lauterbach führt Zeitmangel an. Nelson hält ihm den Zeitvergleich entgegen und formuliert die Wette konkret: Die Verantwortlichen hätten das Leben der Stadionbesucher auf Kochs Entscheidung gesetzt. Das ist Nelsons Vorwurf; Lauterbach weist die Bezeichnung als Wette zurück.", ["Niemand im Lagezentrum gab den Räumungsbefehl. Lauterbach beruft sich auf Zeitmangel. Nelson hält ihm 52 Minuten zwischen dem ersten Funkspruch und dem prognostizierten Einschlag entgegen. Laut Notfallplan sollte die Räumung 15 Minuten dauern.", "Nelson wirft den Verantwortlichen vor, auf einen Abschuss durch Koch gesetzt zu haben. Lauterbach weist die Bezeichnung als Wette zurück."]],
 ["40–42", ["biegler befuerwortet eine verurteilung", "biegler haelt koch fuer (?:den leiter|den verantwortlichen) der stadionraeumung"], "Biegler unterbricht Nelson und erinnert daran, dass Lauterbach als Zeuge vor Gericht steht. Seine Nachfragen entlasten Koch von der Verantwortung für die Räumung.", "Biegler klärt mit drei Fragen, dass der bayerische Katastrophenschutz für die Räumung zuständig war, Koch diese Aufgabe nicht hatte und selbst nichts an der Besetzung des Stadions ändern konnte.", ["Biegler hinterfragt, wer für eine Räumung zuständig gewesen wäre und ob Lauterbach darüber zuverlässig Auskunft geben kann. Damit lenkt er den Blick auf die Verantwortung der Behörden und die Lage, die Koch bei seiner Entscheidung tatsächlich vorfand."]],
 ["43–46", ["nie kampfpilot", "abitur.*schlecht", "koch (?:ging|zog) ohne (?:fliegerische )?ausbildung in den einsatz"], "Koch besteht das Abitur mit 1,0, wird Kampfpilot und erreicht den Rang eines Majors.", "Nach Eignungsprüfungen in Köln beginnt er in Fürstenfeldbruck den Offiziersanwärterlehrgang. Es folgen Grund- und Fortgeschrittenenausbildung in Arizona, Ausbildung zum Strahlflugzeugführer in Texas und die Eingewöhnung an europäische Flugbedingungen. Die Laufbahn und seine Beurteilungen stützen den Eindruck eines ehrgeizigen, disziplinierten Menschen.", ["Koch schildert eine glückliche Jugend, ein Abitur mit 1,0 und sein Interesse an Physik und Sport. Der Berufswunsch knüpft an den unerfüllten Wunsch seines Vaters an. Koch absolviert die Ausbildung zum Kampfpiloten und wird Major.", "Ein möglicher Eindruck ist der eines leistungsorientierten und disziplinierten Menschen. Das lässt sich am Abitur und am Ausbildungsgang zeigen. Andere Eindrücke sind mit Textbelegen möglich."]],
 ["46–51", ["unendlich viel zeit", "hatte keinen zeitdruck", "koch hatte sich (?:vor dem einsatz )?nie mit dem (?:ernstfall|szenario) befasst"], "Koch beschreibt eine Entscheidung unter engem Zeitdruck. Ausbildung und Einsatzvorbereitung geben ihm keinen fertigen Entscheid für den Einzelfall.", "Er verfolgt den fortgesetzten Kurs und den Sinkflug, wartet nach seiner Darstellung bis zum letzten möglichen Moment und schiesst trotz der bestätigten Weisung. Die fliegerischen Abläufe sind ihm vertraut. Den Konflikt zwischen Gehorsam und dem von ihm erwarteten Einschlag muss er aus seiner Sicht selbst entscheiden. Er hatte den Ernstfall mit Kollegen, Angehörigen, Vorgesetzten und Rechtslehrern besprochen. Im entscheidenden Moment denkt er an seine Frau, seinen Sohn und den Tod (PDF 48–49).", ["Koch beschreibt die letzten Augenblicke aus seiner Sicht als Pilot. Er konnte auf Training und eingeübte Abläufe zurückgreifen.", "Die Entscheidung, ob er gegen die Weisung schiesst, musste er in der konkreten Lage selbst und unter Zeitdruck treffen. Technische Vorbereitung beantwortet diese Entscheidung nicht."]],
 ["50–52, 68–71", ["koch hat die sms gelesen", "koch.*sah.*passagiere.*cockpit", "koch wusste dass (?:der entfuehrer bereits ueberwaeltigt war|die passagiere den entfuehrer ueberwaeltigt hatten)"], "Koch erklärt, dass er den Versuch der Passagiere nicht sah. Die SMS kommt erst in Meisers Aussage zur Sprache.", "Er kennt Entführungsmeldung, Kurs und Sinkflug. Er kann von aussen nicht feststellen, ob die Passagiere ins Cockpit gelangen oder den Entführer überwältigen. Der Vorsitzende sagt später, dass auch das Gericht den Erfolg des Versuchs nicht kennt.", ["Koch kannte die Entführungsmeldung und beobachtete den Flug von aussen. Was sich im Innern der Maschine im entscheidenden Moment abspielte, wusste er nicht sicher.", "Insbesondere konnte er nicht sicher wissen, ob die Passagiere den Entführer noch hätten überwältigen können. Seine Prognose stützte sich auf die von aussen erkennbare Lage."]],
 ["51–56", ["nie vom urteil.*gehoert", "(?:er|koch) (?:hoerte|erfuhr) (?:im gericht|vor gericht) erstmals von der entscheidung aus karlsruhe"], "Koch kannte das Urteil und hatte sich mit dem Problem schon vor dem Einsatz befasst.", "Er verweist auf die Diskussion unter Kampfpiloten. Seine juristische Vorbereitung zeigt, dass er das Abschussverbot kannte. Er hält eine zahlenmässige Abwägung in extremen Fällen trotzdem für möglich. Auf Nelsons Nachfrage kann er keine feste Grenze nennen und verweist auf die Entscheidung im Einzelfall.", ["Koch hatte sich mit dem Urteil des Bundesverfassungsgerichts und dem Abschussverbot beschäftigt. Seine Entscheidung fiel somit vor dem Hintergrund einer ihm bekannten rechtlichen Grenze.", "Er hält die Abwägung in einer extremen Lage dennoch für geboten und stellt der abstrakten Regel die erwarteten Todesopfer eines Einschlags gegenüber."]],
 ["55–57", ["gottgleich und deshalb rechtmaessig", "nelson billigt.*eigenmaechtig", "fuer nelson macht kochs eigenmacht den abschuss (?:rechtens|rechtmaessig)"], "Nelson kritisiert Kochs eigenmächtigen Anspruch, die Grenze zwischen zu opfernden und zu rettenden Menschen festzulegen.", "Das Organentnahmebeispiel und die steigenden Zahlenverhältnisse führen zur Frage, wer die Grenze festlegt. Der Vorwurf überzeugt mich als Kritik an unkontrollierter Entscheidungsmacht. Sein Rettungsziel erklärt den Entschluss, beantwortet aber die Frage nach dieser Macht noch nicht.", ["Nelson wirft Koch vor, eigenmächtig darüber entschieden zu haben, wer leben und wer sterben soll. Das Bild vom gottgleichen Handeln greift diesen Anspruch an.", "Der Vorwurf ist nachvollziehbar, weil die Menschen an Bord keine Wahl hatten. Zugleich kann man einwenden, dass Koch eine unmittelbar drohende Katastrophe abwenden wollte. Entscheidend ist, wie man beide Aspekte gewichtet."]],
 ["57–58", ["nelson haelt aeltere menschen fuer weniger wert", "weniger wert.*nelson", "nelson will (?:die )?menschen nach ihrer (?:verbleibenden )?lebenszeit bewerten"], "Nelson prüft kritisch Kochs Massstab der Restlebenszeit. Sie spricht Menschen mit kurzer Lebenserwartung den Schutz gerade nicht ab.", "Koch hält die Passagiere für ohnehin dem Tod geweiht. Nelson fragt nach fünf Minuten und danach, ob Zeit für einen Abschied bleiben müsste. Ihre Beispiele zeigen, dass auch wenige Minuten für Betroffene einen eigenen Wert haben und dass Koch keine begründete Grenze nennt.", ["Nelson fragt nach fünf Minuten Restlebenszeit und danach, ob die Passagiere noch Zeit für einen Abschied haben dürften.", "Die verbleibenden Lebensjahre liefern keinen Massstab für die Würde eines Menschen. Wer dennoch nach Zahlen entscheiden will, muss begründen, warum gerade die Zahl der Betroffenen und keine andere Rechengrösse zählen soll."]],
 ["58–61", ["ticket erteilt.*einwilligung", "fluggast willigt.*gezielte toetung", "mit der buchung akzeptiert man laut nelson die (?:absichtliche|gezielte) toetung"], "Die Bereitschaft, ein allgemeines Flugrisiko einzugehen, ist keine Zustimmung zu einer absichtlichen Tötung.", "Koch führt das freiwillige Einsteigen als Übernahme des Todesrisikos an. Nelson hält ihm entgegen, dass die Passagiere dadurch kein Recht aufgeben. Ihre Widerrede überzeugt, weil sich ein Risiko der Reise von der gezielten Entscheidung eines Dritten unterscheidet.", ["Koch behandelt den Tod als Risiko, das jeder Fluggast beim Einsteigen in Kauf nimmt.", "Nelsons Widerrede trennt die Übernahme eines allgemeinen Flugrisikos von der Einwilligung, absichtlich durch den Staat getötet zu werden. Ein Flugticket enthält keine solche Einwilligung."]],
 ["60–64", ["koch hielt den einschlag.*ausgeschlossen", "koch erwartete keinen einschlag", "koch ging von einer (?:sicheren|ungefaehrlichen) landung aus"], "Koch rechnet gerade mit einem Einschlag und begründet damit seine Kritik am Abschussverbot.", "Sein Einwand hat Gewicht, wenn der Einschlag unmittelbar droht. Die Prognose bleibt jedoch unsicher; gerade die im Flugzeug eingeschlossenen Unbeteiligten sind durch das Verfassungsprinzip geschützt. Ich halte diese Unsicherheit für entscheidend, wenn man seine Behauptung einer zwangsläufigen Katastrophe beurteilt.", ["Koch meint, die Einhaltung des Abschussverbots hätte in dieser Lage zur Katastrophe im Stadion geführt.", "Dagegen steht, dass der Einschlag eine Prognose war und dass der Verfassungsgrundsatz gerade in Extremlagen die Menschen an Bord schützt. Eine Stellungnahme muss beide Punkte abwägen."]],
 ["55–64", ["stellte koch keine nachfragen", "nelson.*liess koch unwidersprochen", "nelson laesst kochs zahlenargument (?:vollstaendig )?unkommentiert"], "Nelson stellt wiederholt Nachfragen, verändert die Beispiele und verlangt eine Begründung für Kochs Grenze.", "Beim Organentnahmebeispiel variiert sie das Zahlenverhältnis. Danach fragt sie nach Minuten verbleibender Lebenszeit und der Möglichkeit eines Abschieds. So prüft sie nacheinander, ob Anzahl, Restlebenszeit oder freiwillig eingegangenes Risiko seine Entscheidung tragen.", ["Nelson prüft Kochs Annahmen mit kurzen Nachfragen und zugespitzten Gegenbeispielen. Sie zwingt ihn, seine Begründung auch dann zu verteidigen, wenn die Betroffenen einzeln betrachtet werden.", "So legt sie die Grenzen seiner Gewissheit und den Widerspruch zwischen seinem Rettungsziel und der Tötung Unbeteiligter offen."]],
 ["65–71", ["meiser ist die staatsanwaeltin", "meiser vertritt die anklage", "meiser verteidigt koch als (?:anwaeltin|verteidigerin)"], "Meiser ist Nebenklägerin und Zeugin. Nelson vertritt die Staatsanwaltschaft.", "Meiser wartet am Flughafen auf ihren Mann und erfährt von der Entführung und dem Abschuss. Vor Gericht fragt sie, ob die Passagiere ins Cockpit gelangt seien. Falls sie den Entführer hätten stoppen können, wäre der Abschuss aus ihrer Sicht möglicherweise vermeidbar gewesen.", ["Franziska Meiser ist Nebenklägerin und wird als Zeugin vernommen. Ihr Mann kam beim Abschuss ums Leben.", "Sie schildert den Verlust aus ihrer persönlichen Perspektive. Ihre Aussage macht aus der Zahl der Opfer den Tod eines konkreten Menschen mit Familie und Geschichte."]],
 ["67–73", ["sms belegt die sichere rettung", "ihr mann wurde gerettet", "vorsitzende bestaetigt dass die passagiere ins cockpit (?:gelangten|gekommen sind)"], "Die SMS berichtet den Versuch, ins Cockpit zu gelangen. Ob dieser Versuch erfolgreich war, bleibt offen.", "Meiser erlebt die Verspätung, erhält die SMS und wird von der Polizei informiert. Auf der Bank schaut sie weiter auf die Türen und hofft, ihr Mann werde doch erscheinen. Später erhält sie seinen linken Schuh. Ihre Frage nach dem Cockpit zeigt, dass sie wissen will, ob der Tod vermeidbar war; das ist ein aus ihrer Aussage erschlossenes Motiv.", ["Meiser rekonstruiert den Kontakt zu ihrem Mann und die Zeit der Ungewissheit bis zur Nachricht von seinem Tod.", "Ihre Beteiligung am Prozess lässt sich als Versuch verstehen, das Geschehen aufzuklären und ihrem Mann Gehör zu verschaffen. Die konkreten Erinnerungen zeigen, wie gegenwärtig der Verlust für sie bleibt."]],
 ["68–73", ["erzaehlt keine erinnerungen", "meiser bleibt voellig unbeteiligt", "meiser berichtet von keinem (?:persoenlichen )?gegenstand ihres mannes"], "Meiser erzählt konkrete Erinnerungen, etwa von der Wartebank und vom linken Schuh ihres Mannes.", "Auf mich wirkt sie zugleich gefasst und erschüttert. Sie erinnert sich genau an den Schuh, während sie bei der Nachricht am Flughafen zunächst weder weinen noch zu Hause anrufen kann. Der Gegensatz zwischen sachlichem Detail und sichtbarem Schock prägt meinen Eindruck.", ["Meiser kann durch ihre genaue Schilderung zugleich gefasst und tief betroffen wirken.", "Als Beleg eignet sich, wie sie von den letzten Nachrichten und vom Warten erzählt. Eine andere Wirkung ist möglich, wenn sie an einer konkreten Stelle begründet wird."]],
 ["75–81", ["nelson fordert.*freispruch", "staatsanwaeltin beantragt freispruch", "anklage will koch wegen seines motivs (?:straflos lassen|freisprechen)"], "Nelson beantragt eine Verurteilung. Sie unterscheidet Kochs Persönlichkeit und Motiv von der Frage nach seiner Schuld.", "Sie stellt die Passagiere als einzelne Rechtsträger in den Mittelpunkt, prüft die Abwägung anhand ethischer Beispiele und lehnt die Entschuldigung durch einen übergesetzlichen Notstand ab. Das persönliche Rettungsmotiv kann anerkannt werden, ohne die absichtliche Tötung der Passagiere straflos zu lassen.", ["Nelson fordert eine Verurteilung wegen Mordes. Sie unterscheidet die persönliche Anständigkeit und das Rettungsmotiv Kochs von der strafrechtlichen Beurteilung der absichtlichen Tötung.", "Für sie dürfen unschuldige Menschen nicht zur Rettung anderer als Mittel benutzt werden. Auch eine grosse Zahl geretteter Menschen hebt diese Grenze nicht auf."]],
 ["76–81", ["notstand ist im strafgesetzbuch geregelt", "notstand steht im grundgesetz", "fuer nelson rechtfertigt der ungeschriebene notstand den abschuss (?:eindeutig|vollstaendig)"], "Der übergesetzliche Notstand ist ein möglicher ungeschriebener Entschuldigungsgrund. Nelson lehnt ihn für diesen Fall ab.", "Die Weiche lenkt eine bestehende Gefahr um. Beim Stoss von der Brücke wird ein Mensch selbst zum Rettungsmittel. Der Abschuss ähnelt für Nelson der zweiten Konstellation, weil die Passagiere bewusst geopfert werden. Die Beispiele prüfen unsere Intuition, ersetzen aber keine rechtliche Regel. Prinzipien schützen jeden Einzelnen auch dann, wenn die erwartete Bilanz eine Ausnahme verlockend erscheinen lässt.", ["Die Beispiele mit der Weiche und dem Stoss von der Brücke prüfen, warum Menschen zwischen dem Umlenken einer Gefahr und der gezielten Benutzung eines Menschen als Rettungsmittel unterscheiden.", "Nelson lehnt eine Entschuldigung durch einen übergesetzlichen Notstand in diesem Fall ab. Prinzipien sollen den Einzelnen gerade dort schützen, wo Empörung oder ein erwarteter Nutzen dazu verleiten, Ausnahmen zu machen."]],
 ["79–81", ["artikel 1.*erlaubt die verrechnung", "menschenwuerde.*nur.*mehrheit", "wuerdesatz steht im (?:strafgesetzbuch|stgb)"], "Artikel 1 Absatz 1 schützt die Würde jedes Menschen. Nelson leitet daraus ein Verbot ab, die Passagiere als Mittel für die Rettung anderer zu behandeln.", "Die Würde ist unantastbar; alle staatliche Gewalt muss sie achten und schützen. Für Nelson behält jeder Passagier diesen Anspruch unabhängig von der Zahl der bedrohten Menschen im Stadion.", ["Der Satz steht in Artikel 1 Absatz 1 des Grundgesetzes. Die Menschenwürde verpflichtet den Staat zur Achtung und zum Schutz jedes Menschen.", "Für Nelson folgt daraus, dass die Passagiere auch im Notfall nicht zu blossen Objekten einer staatlichen Rettungsrechnung werden dürfen."]],
 ["81–83", ["kant haelt eine luege.*zwingend", "kant empfiehlt.*luege", "kant erlaubt (?:in diesem beispiel )?die taeuschung des moerders"], "Biegler greift gerade Kants striktes Lügenverbot an: Selbst gegenüber dem Mörder soll man nach diesem Beispiel nicht lügen.", "Biegler zeigt, wie eine ausnahmslose Regel dem Täter helfen kann. Daraus entwickelt er seine Gegenposition zu Nelson. Die Richter in Karlsruhe haben über die staatliche Ermächtigung zum Abschuss entschieden. Die persönliche Strafbarkeit Kochs in dieser konkreten Lage blieb offen.", ["Biegler antwortet mit Kants Beispiel vom Mörder, der nach dem Versteck seines Opfers fragt. Er kritisiert die Konsequenz eines ausnahmslosen Prinzips, wenn es die Rettung des Opfers verhindert.", "Seine Pointe ist die Trennung zwischen dem verfassungsgerichtlichen Urteil über eine staatliche Abschussermächtigung und der Entscheidung über die persönliche Strafbarkeit Kochs. Letztere hat das Verfassungsgericht nicht getroffen."]],
 ["82–84", ["biegler haelt die verurteilung fuer das kleinere uebel", "biegler beantragt verurteilung", "biegler nennt die verurteilung den (?:richtigen|gerechten) ausgang"], "Biegler nennt den Abschuss das kleinere Übel und beantragt Freispruch.", "Er bestreitet anhand der gerichtlich erlaubten Trennung siamesischer Zwillinge und eines Vergleichsfalls mit einem führerlosen Flugzeug, dass jede Abwägung ausgeschlossen sei. Für ihn wiegt die erwartete Katastrophe schwerer als der Abschuss. Eine Verurteilung würde seiner Auffassung nach die staatliche Gegenwehr schwächen und künftigen Tätern signalisieren, dass viele Geiseln sie schützen.", ["Biegler vergleicht die Folgen des Handelns und des Unterlassens. Für ihn war der Abschuss unter den angenommenen Umständen das kleinere Übel.", "Eine Verurteilung würde nach seiner Argumentation jemanden bestrafen, der unter extremem Druck eine grössere Katastrophe verhindern wollte, und hätte Folgen dafür, wie Verantwortliche in vergleichbaren Lagen handeln."]],
 ["84–86", ["publikum darf nicht abstimmen", "schoeffen haben keine stimme", "vorsitzende verkuendet das urteil bevor das publikum (?:entscheidet|abstimmt)"], "Das Publikum stimmt als Schöffen ab. Die Mehrheit bestimmt die zu verkündende Urteilsfassung.", "Koch erhält das letzte Wort und schliesst sich Biegler an. Der Vorsitzende übergibt die Entscheidung den Schöffen. Sie wählen zwischen Verurteilung und Freispruch, danach wird die entsprechende Fassung verkündet.", ["Der Vorsitzende schliesst die Verhandlung und übergibt die Entscheidung den Schöffen, also dem Publikum.", "Sie müssen zwischen Verurteilung und Freispruch entscheiden. Das Abstimmungsergebnis bestimmt, welche der beiden Urteilsfassungen verkündet wird."]],
 ["32–33, 79–81, 87–93", ["niemand an bord starb", "keine menschen an bord starben", "an bord gab es keine (?:todesopfer|toten)"], "Alle 164 Menschen an Bord starben. Ein Freispruch lässt sich mit einer möglichen Entschuldigung begründen; er bestreitet die Todesopfer nicht.", "Ich würde Koch verurteilen. Er wusste, dass 164 Menschen an Bord waren, und schoss nach zweimaliger Bestätigung des Verbots. Die Passagiere waren für die Entführung nicht verantwortlich. Wenn der Staat ihre Tötung allein mit der grösseren Zahl bedrohter Zuschauer begründet, macht er ihren Schutz von einer Rechnung abhängig. Für einen Freispruch spricht, dass Koch unter extremem Druck stand und die Zuschauer retten wollte. Nach dem Sinkflug erschien ihm ein Einschlag unmittelbar bevorstehend. Dieses Motiv erklärt, warum er schoss, und verdient bei der Schuldfrage Gewicht. Der befürchtete Einschlag war dennoch eine Prognose. Auch blieb offen, ob die Passagiere den Entführer hätten stoppen können. Deshalb überzeugt mich die Entschuldigung im konkreten Fall nicht. Meine Entscheidung richtet sich gegen die absichtliche Tötung der Passagiere unter diesen Umständen. Sie setzt nicht voraus, dass ich Koch für einen Menschen ohne Gewissen halte.", ["Beispiel für eine Verurteilung. Ich würde Koch verurteilen, weil er bewusst 164 Menschen tötete, die für die Entführung keine Verantwortung trugen.", "Sein Rettungsmotiv und der Zeitdruck sind gewichtige Gründe für einen Freispruch. Dennoch beruhte der erwartete Einschlag auf einer Prognose. Die Passagiere hatten Anspruch darauf, dass der Staat ihr Leben nicht gezielt opfert. Eine begründete Gegenposition kann die individuelle Entschuldigung in den Mittelpunkt stellen."]],
 ["87–93", ["beide urteile sprechen koch frei", "beide urteile verurteilen koch", "in keiner der fassungen erhaelt koch eine (?:freiheitsstrafe|haftstrafe)"], "Eine Fassung verurteilt Koch zu lebenslanger Freiheitsstrafe, die andere spricht ihn frei. Beide gehen vom selben Abschuss und denselben Todesopfern aus.", "Im Schuldspruch bleibt die absichtliche Tötung Mord; das Gericht erkennt keine Entschuldigung an. Im Freispruch hält das Gericht einen ungeschriebenen Entschuldigungsgrund für tragfähig und würdigt Kochs selbstloses Rettungsmotiv. Mein Urteil aus der vorherigen Aufgabe liegt näher beim Schuldspruch, weil ich die Unsicherheit der Prognose und den Schutz der Passagiere stärker gewichte. Mit dem Freispruch teile ich die Einschätzung, dass Koch aus einem ernsthaften Gewissenskonflikt handelte. Ich folge ihm bei der strafrechtlichen Entschuldigung nicht.", ["Die Verurteilung wertet den Abschuss als Mord und verhängt lebenslange Freiheitsstrafe. Sie verwirft einen übergesetzlichen Entschuldigungsgrund.", "Die Freispruchsfassung erkennt bei gleicher Tat einen übergesetzlichen Notstand als persönlichen Entschuldigungsgrund an. Im Vergleich mit dem eigenen Urteil ist entscheidend, ob man diese Ausnahme für tragfähig hält und warum."]],
];

function readerOriginalQuestions(m){
 const group=READER_ORIGINAL_QUESTIONS[m.id];
 if(!group)return '';
 return `<section class="section card" aria-labelledby="readerOriginalQuestionsTitle">
 <h2 id="readerOriginalQuestionsTitle">Hauptauftrag · Fragen zur Lektüre</h2>
 <ul role="list" style="list-style:none;padding-inline-start:0">${group.questions.map((question,index)=>`<li>${escape(question)}${readerOriginalAnswer(group.first+index)}</li>`).join('')}</ul>
 </section>`;
}
function originalTextReferences(pages){
 return pages.split(', ').map(range=>feedbackReference(parseInt(range,10),'Textbeleg · '+range)).join(' ');
}
function readerOriginalAnswer(number){
 const [pages,,,model]=READER_ORIGINAL_FEEDBACK[number-1];
 return `<div data-original-answer="${number}">
 ${note('original-terror-'+number,'Deine Antwort')}
 <button type="button" class="secondary small" data-original-check>Antwort prüfen</button>
 <div class="feedback-result" data-original-result aria-live="polite"></div>
 <details><summary>Musterlösung</summary>
 <p>${escape(model)}</p>
 ${originalTextReferences(pages)}
 </details></div>`;
}
function originalAnswerErrors(number,response){
 const [pages,patterns,correction]=READER_ORIGINAL_FEEDBACK[number-1];
 const errors=TERROR_FEEDBACK.check(readerCurrentModule().id+'-0',response)?.errors||[];
 const sentences=response.split(/(?<![0-9])[.!?]+|[.!?]+(?![0-9])|[;\n]+/);
 for(const sentence of sentences){
  const excerpt=sentence.trim(), normalized=TERROR_FEEDBACK.normalize(excerpt);
  if(/[«»„“"”]/.test(excerpt)||/\b(?:falsch|irrtum|widerleg\w*|bezweifelt)\b/.test(normalized))continue;
  const matches=patterns.some(pattern=>{
   const match=new RegExp('\\b(?:'+pattern+')\\b').exec(normalized);
   if(!match)return false;
   const before=normalized.slice(0,match.index).trim().split(' ').slice(-4).join(' ');
   return !/\b(?:nicht|nie|kein\w*)\b/.test(before);
  });
  if(matches&&!errors.some(error=>TERROR_FEEDBACK.normalize(error.excerpt)===normalized)){
   errors.push({excerpt,correction,page:parseInt(pages,10)});
  }
 }
 return errors;
}
function updateOriginalFeedback(answer){
 if(!answer.isConnected)return;
 const number=Number(answer.dataset.originalAnswer);
 const [pages,,,,hints]=READER_ORIGINAL_FEEDBACK[number-1];
 const response=answer.querySelector('textarea').value.trim();
 const result=answer.querySelector('[data-original-result]');
 if(!response){result.textContent='Schreibe zuerst eine Antwort.';return;}
 const errors=originalAnswerErrors(number,response);
 result.innerHTML=`
 ${errors.length?errors.map(error=>`<article class="feedback-error">
 <p><strong>Möglicher Sachfehler</strong> <q>${escape(error.excerpt)}</q></p>
 <p>${escape(error.correction)}</p>${feedbackReference(error.page,'Zur Textstelle')}
 </article>`).join(''):'<p>Das Sofortfeedback hat keinen eindeutigen Sachfehler erkannt. Prüfe deine Antwort anhand der Textstellen.</p>'}
 <details open><summary>Prüfpunkte für deine Antwort</summary>
 <ul>${hints.map(hint=>`<li>${escape(hint)}</li>`).join('')}</ul>
 ${originalTextReferences(pages)}</details>`;
}
const originalFeedbackTimers=new WeakMap();
function readerQuestionHTML(m){const q=readerQuestion;return `<div class="question-tabs" role="group" aria-label="Analyseaufträge">${m.tasks.map((_,i)=>`<button class="${i===q?'':'secondary'} small" data-reader-question="${i}" aria-pressed="${i===q}">Auftrag ${i+1}${state.notes['leseraum-'+m.id+'-'+i]?.text?.trim()?' · ✓':''}</button>`).join('')}</div><span class="eyebrow">AUFTRAG ${q+1} / ${m.tasks.length}</span><h2 id="readerQuestionTitle" tabindex="-1">${m.tasks[q]}</h2>${note('leseraum-'+m.id+'-'+q,m.title+' · Auftrag '+(q+1),'Notiere zuerst deine Beobachtung, dann einen Beleg und deine Deutung.')}<div class="feedback-toolbar"><button type="button" class="accent small" data-feedback-check>Antwort prüfen</button><span>Automatisches Feedback nach einer kurzen Schreibpause · lokal auf deinem Gerät</span></div><div id="readerFeedback" class="reader-feedback" aria-live="polite" aria-atomic="false">${readerFeedbackHTML(m.id+'-'+q,state.notes['leseraum-'+m.id+'-'+q]?.text||'')}</div><details class="feedback-method"><summary>Wie werden meine Formulierungen erkannt?</summary><div>Der lokale Sprachabgleich berücksichtigt Synonyme, Wortformen, Umlaute, ss/ß, mehrere passende Begriffe im Satz und einzelne Tippfehler in längeren Wörtern. Er erkennt nicht jede Bedeutung oder Ironie. Ein gefundener Begriff beweist keine korrekte Argumentation. Bei abweichenden Lesarten entscheiden deine Belege; fehlende Treffer sind kein automatisches Falschurteil.</div></details><div class="reader-next"><button class="secondary small" data-reader-question="${q-1}" ${q===0?'disabled':''}>← Zurück</button><button class="small" data-reader-question="${q+1}" ${q===m.tasks.length-1?'disabled':''}>Weiter →</button></div>`;}
function readerCurrentModule(){return D.modules.find(m=>m.id===location.hash.split('/')[1]);}
function initReader(){
 const root=document.getElementById('readerWorkspace');if(!root?.dataset?.module)return;
 const m=readerCurrentModule();readerPdfPage=readerScene(m.id)?.page||parseInt(m.pages);
 if(readerPdf)drawReaderPdf(readerPdfPage);else if(!readerRestored){readerRestored=true;readPdfCache().catch(()=>null).then(f=>{if(!readerPdf&&readerPdfLoading===0){if(f)loadReaderPdf(f,undefined);else loadDefaultReaderPdf();}});}
 if(readerFilmEnabled&&readerScene(m.id))mountReaderVideo(false);
 if(readerEvents)return;readerEvents=true;
 main.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset,m=readerCurrentModule();if(!m)return;
 if('originalCheck' in a){
  const answer=b.closest('[data-original-answer]');
  clearTimeout(originalFeedbackTimers.get(answer));
  updateOriginalFeedback(answer);
  return;
 }
 if(a.readerPart!==undefined){const n=Number(a.readerPart),parts=D.scenes.find(s=>s.id===m.id)?.parts;if(parts&&n>=0&&n<parts.length){readerPart=n;render();}return;}
 if('readerPlay'in a||'readerRestart'in a){readerFilmEnabled=true;mountReaderVideo(true);}
 if(a.readerQuestion!==undefined){const n=Number(a.readerQuestion);if(n>=0&&n<m.tasks.length){readerQuestion=n;document.getElementById('readerQuestionPanel').innerHTML=readerQuestionHTML(m);document.getElementById('readerQuestionTitle').focus({preventScroll:true});}}
 if(a.pdfZoom){readerPdfZoom=Math.max(1,Math.min(2.5,readerPdfZoom+(a.pdfZoom==='in'?.25:-.25)));document.getElementById('readerZoom').textContent=Math.round(readerPdfZoom*100)+'%';drawReaderPdf(readerPdfPage);}
 if('pdfPrev'in a)drawReaderPdf(readerPdfPage-1);if('pdfNext'in a)drawReaderPdf(readerPdfPage+1);if('pdfHome'in a)drawReaderPdf(readerScene(m.id)?.page||parseInt(m.pages));
 if('pdfRetry'in a)loadDefaultReaderPdf();
 if('pdfForget'in a){readerPdfLoading++;readerPdfJob++;readerPdfRender?.cancel();readerPdfRender=null;readerPdf?.destroy();readerPdf=null;readerPdfName='';if(pdfURL)URL.revokeObjectURL(pdfURL);pdfURL='';writePdfCache(null).catch(()=>{});render();loadDefaultReaderPdf();toast('Eigene PDF entfernt. Die eingebundene Ausgabe wird geöffnet. Deine Notizen bleiben erhalten.');}
 });
 main.addEventListener('change',e=>{const el=e.target;if(el.id==='readerPdfInput'&&el.files[0])loadReaderPdf(el.files[0],document.getElementById('rememberReaderPdf').checked);if(el.id==='readerPage')drawReaderPdf(Number(el.value));if(el.id==='readerLocalFilm'&&el.files[0]){if(filmObjectURL)URL.revokeObjectURL(filmObjectURL);filmObjectURL=URL.createObjectURL(el.files[0]);readerFilmEnabled=true;if(readerVideoCleanup){readerVideoCleanup();readerVideoCleanup=null;}document.getElementById('readerVideo')?.remove();mountReaderVideo(false);}});
 main.addEventListener('input',e=>{
  const answer=e.target.closest('[data-original-answer]');
  if(answer && e.target.matches('textarea')){
   clearTimeout(originalFeedbackTimers.get(answer));
   originalFeedbackTimers.set(answer,setTimeout(()=>updateOriginalFeedback(answer),650));
  }
  if(e.target.id==='readerSeek'){const v=document.getElementById('readerVideo');if(v?.readyState>=1)v.currentTime=Number(e.target.value);}});
}
function mountReaderVideo(play){
 const m=readerCurrentModule(),s=readerScene(m?.id);if(!s)return;const mount=document.getElementById('readerVideoMount');if(!mount)return;
 let v=document.getElementById('readerVideo');if(v){v.currentTime=s.start;if(play)v.play().catch(()=>{});return;}
 mount.innerHTML='<video id="readerVideo" controls playsinline preload="metadata" aria-label="Filmszene: '+escape(s.title)+'"></video>';
 v=document.getElementById('readerVideo');const status=document.getElementById('readerFilmStatus'),seek=document.getElementById('readerSeek'),clock=document.getElementById('readerClock');
 const update=()=>{if(!v.isConnected)return;if(v.currentTime>=s.end){v.pause();status.textContent='Szenenende erreicht. Vergleiche jetzt die Textstelle oder wähle die nächste Szene.';}const t=Math.max(s.start,Math.min(s.end,v.currentTime));seek.value=t;clock.textContent=fmtTime(t-s.start)+' / '+fmtTime(s.end-s.start);};
 v.addEventListener('loadedmetadata',()=>{if(v.duration<s.end){status.textContent='Diese Filmfassung ist zu kurz für die Kapitelmarken. Wähle die bereitgestellte Fassung oder nutze die Filmwerkstatt.';return;}v.currentTime=s.start;status.textContent=fmtTime(s.start)+'–'+fmtTime(s.end)+' · '+s.note;if(play)v.play().catch(()=>{status.textContent='Szene ist bereit. Starte sie mit der Wiedergabetaste.';});});
 v.addEventListener('play',()=>{if(v.currentTime<s.start||v.currentTime>=s.end)v.currentTime=s.start;});
 v.addEventListener('seeking',()=>{if(v.currentTime<s.start)v.currentTime=s.start;else if(v.currentTime>s.end)v.currentTime=s.end;});
 v.addEventListener('timeupdate',update);v.addEventListener('error',()=>{status.textContent='Der Film konnte nicht geladen werden. Öffne die Filmquelle oder wähle dieselbe Fassung als lokale Datei.';});
 v.src=filmObjectURL||D.videos[0].src;const timer=setInterval(()=>{if(!v.paused)update();},100);readerVideoCleanup=()=>{clearInterval(timer);v.pause();v.removeAttribute('src');v.load();};
}
function stopReader(){if(readerVideoCleanup){readerVideoCleanup();readerVideoCleanup=null;}readerPdfJob++;readerPdfRender?.cancel();readerPdfRender=null;}
function pdfCache(){return new Promise((resolve,reject)=>{if(!window.indexedDB){reject(Error('Lokaler Dateispeicher nicht verfügbar'));return;}const req=indexedDB.open('terror-reader-media',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function readPdfCache(){const db=await pdfCache();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readonly'),r=tx.objectStore('files').get('text');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);tx.oncomplete=()=>db.close();});}
async function writePdfCache(file){const db=await pdfCache();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');file?tx.objectStore('files').put(file,'text'):tx.objectStore('files').delete('text');tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>{db.close();reject(tx.error);};});}
async function loadDefaultReaderPdf(){
 if(readerDefaultRequest)return readerDefaultRequest;
 const version=readerPdfLoading;
 const status=document.getElementById('readerPdfStatus');if(status)status.textContent='Die eingebundene Textausgabe wird geladen …';
 readerDefaultRequest=(async()=>{
  try{const response=await fetch(READER_TEXT_URL);if(!response.ok)throw Error('HTTP '+response.status);
   const blob=await response.blob();if(version!==readerPdfLoading)return;
   await loadReaderPdf(new File([blob],'Schirach_Terror_9783641203290.pdf',{type:'application/pdf'}),undefined);
  }catch(err){if(version===readerPdfLoading){const status=document.getElementById('readerPdfStatus');if(status)status.textContent='Der Text konnte nicht geladen werden. Prüfe die Verbindung und wähle «Text erneut laden» oder «PDF direkt öffnen».';}}
  finally{readerDefaultRequest=null;}
 })();return readerDefaultRequest;
}
async function loadReaderPdf(file,remember){
 const loadId=++readerPdfLoading;const status=()=>document.getElementById('readerPdfStatus');if(file.type!=='application/pdf'&&!file.name?.toLowerCase().endsWith('.pdf')){toast('Bitte eine PDF-Datei wählen.');return;}
 if(status())status().textContent='PDF wird lokal geöffnet …';
 try{const lib=await import('./vendor/pdfjs/pdf.mjs');lib.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdfjs/pdf.worker.mjs',location.href.split('#')[0]).href;
 const pdf=await lib.getDocument({data:await file.arrayBuffer(),standardFontDataUrl:new URL('./vendor/pdfjs/standard_fonts/',location.href.split('#')[0]).href,isEvalSupported:false}).promise;
 if(loadId!==readerPdfLoading){pdf.destroy();return;}readerPdfJob++;readerPdfRender?.cancel();readerPdfRender=null;readerPdf?.destroy();readerPdf=pdf;readerPdfName=file.name||'Deine PDF';if(pdfURL)URL.revokeObjectURL(pdfURL);pdfURL=URL.createObjectURL(file);
 let cacheFailed=false;try{if(remember!==undefined)await writePdfCache(remember?file:null);}catch(_){cacheFailed=remember;}
 const m=readerCurrentModule();if(m)await drawReaderPdf(readerScene(m.id)?.page||parseInt(m.pages));if(cacheFailed)toast('PDF geöffnet. Dauerhaftes Merken ist hier nicht möglich.');
 }catch(err){if(status())status().textContent='Die PDF konnte nicht geöffnet werden. Prüfe die Datei; verschlüsselte PDFs müssen zuerst entsperrt werden.';}
}
async function drawReaderPdf(page){
 const mount=document.getElementById('readerPdfMount');if(!mount)return;
 if(!readerPdf){document.getElementById('readerPdfStatus').textContent='Die Textausgabe wird geladen. Falls sie nicht erscheint, wähle «Text erneut laden».';return;}
 const pdf=readerPdf,job=++readerPdfJob;readerPdfPage=Math.max(1,Math.min(pdf.numPages,Math.trunc(Number(page))||1));
 readerPdfRender?.cancel();readerPdfRender=null;
 const input=document.getElementById('readerPage');input.value=readerPdfPage;input.max=pdf.numPages;document.getElementById('readerPageCount').textContent='/ '+pdf.numPages;
 document.getElementById('readerPdfStatus').textContent=readerPdfName+' · Seite '+readerPdfPage+(pdf.numPages!==103?' · Andere Ausgabe: Prüfe die Zuordnung selbst.':'');
 document.getElementById('readerPdfLinks').innerHTML=`<a href="${pdfURL}#page=${readerPdfPage}" target="_blank" rel="noopener">PDF gross öffnen ↗</a> <button class="secondary small" data-pdf-forget>Zur eingebundenen Ausgabe zurückkehren</button>`;
 try{const p=await pdf.getPage(readerPdfPage);if(job!==readerPdfJob||!mount.isConnected)return;
 const base=p.getViewport({scale:1}),width=Math.max(250,mount.clientWidth-24)*readerPdfZoom,ratio=Math.min(window.devicePixelRatio||1,2),viewport=p.getViewport({scale:width/base.width*ratio});
 const canvas=document.createElement('canvas');canvas.width=viewport.width;canvas.height=viewport.height;canvas.style.width=width+'px';canvas.style.maxWidth='none';canvas.setAttribute('role','img');canvas.setAttribute('aria-label','PDF-Seite '+readerPdfPage);mount.replaceChildren(canvas);mount.scrollTop=0;
 const task=p.render({canvasContext:canvas.getContext('2d'),viewport});readerPdfRender=task;await task.promise;if(job===readerPdfJob)readerPdfRender=null;
 const text=await p.getTextContent();if(job!==readerPdfJob||!mount.isConnected)return;const accessible=document.createElement('div');accessible.className='sr-only';accessible.textContent=text.items.map(x=>x.str).join(' ');mount.appendChild(accessible);
 }catch(err){if(err.name!=='RenderingCancelledException'&&job===readerPdfJob)document.getElementById('readerPdfStatus').textContent='Diese Seite konnte nicht dargestellt werden. Nutze «PDF gross öffnen».';}
}
